function validate([nums, k]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each value is between 1 and nums.length.';
  if (!Number.isInteger(k) || k < 0 || k > n) return 'k is between 0 and nums.length.';
  return null;
}

