function longestEqualSubarray(nums, k) {
  // Keep one value inside an original range and delete everything else in that range.
  let best = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      const length = end - start + 1;
      for (let p = start; p <= end; p++) {
        let count = 0;
        for (let q = start; q <= end; q++) if (nums[q] === nums[p]) count++;
        if (length - count <= k && count > best) best = count;
      }
    }
  }
  return best;
}

