function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  // Few distinct values give long runs to join; many give short ones.
  const top = rand() < 0.5 ? Math.min(n, 1 + Math.floor(rand() * 4)) : n;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const cap = size === 'large' ? 60 : 4;
  const k = rand() < 0.6 ? Math.floor(rand() * (Math.min(n, cap) + 1)) : Math.floor(rand() * (n + 1));
  return [nums, k];
}
